import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import { Game } from './game/engine';
import type { HudData, MsgKind, ShopData, Summary } from './game/engine';
import { loadRecords } from './game/config';
import type { DiffId, UpgId } from './game/config';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import Workshop from './components/Workshop';
import { GameOverScreen, Menu, PauseScreen } from './components/Screens';

type Screen = 'menu' | 'play' | 'paused' | 'shop' | 'over';
const PREFS_KEY = 'abismo-prefs';

function loadPrefs(): { diff: DiffId; muted: boolean } {
  try { const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}'); return { diff: p.diff || 'normal', muted: !!p.muted }; }
  catch { return { diff: 'normal', muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const timers = useRef<number[]>([]);
  const msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [shop, setShop] = useState<ShopData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));

  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.filter(x => x.text !== text).slice(-3), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), kind === 'big' ? 3400 : 2300));
  }, []);
  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); setScreen('paused'); }
    else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
    else if (g.mode === 'shop') { g.resume(); setShop(null); setScreen('play'); }
  }, []);
  const openShop = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'shop') { g.resume(); setShop(null); setScreen('play'); return; }
    if (g.openShop()) { setShop(g.getShop()); setScreen('shop'); }
  }, []);

  useEffect(() => {
    if (!wrapRef.current) return;
    const g = new Game(wrapRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 160, spread: 95, origin: { y: 0.35 }, colors: ['#5ff5ff', '#5eead4', '#ffd34d', '#ff5ad8'] });
      },
    });
    g.input.onPause = togglePause;
    g.input.onShop = openShop;
    g.input.onAnyKey = () => g.sfx.unlock();
    gameRef.current = g;
    return () => {
      timers.current.forEach(t => clearTimeout(t)); timers.current = [];
      g.dispose(); gameRef.current = null;
    };
  }, [pushMsg, togglePause, openShop]);
  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, muted })); } catch { /* sin almacenamiento */ }
  }, [diff, muted]);

  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null); setShop(null);
    g.setMuted(muted); g.start(diff); setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setShop(null); setScreen('menu'); setRecords(loadRecords()); };
  const shopAct = (fn: (g: Game) => void) => { const g = gameRef.current; if (!g) return; fn(g); setShop(g.getShop()); };
  const sonarRef = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.setSonarCanvas(c); }, []);
  const inGame = screen === 'play' || screen === 'paused' || screen === 'shop';

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#020c18] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => gameRef.current?.sfx.unlock()} />
      <div className="pointer-events-none absolute inset-0" style={{ background: 'radial-gradient(ellipse at 50% 45%, transparent 55%, rgba(0,4,10,0.55) 100%)' }} />
      {inGame && (
        <Hud hud={hud} msgs={msgs} muted={muted} touch={touch && screen === 'play'} input={gameRef.current?.input ?? null}
          onMute={() => setMuted(m => !m)} onPause={togglePause} onShop={openShop}
          onSonar={() => gameRef.current?.input.onSonar?.()} onTorpedo={() => gameRef.current?.input.onTorpedo?.()} sonarRef={sonarRef} />
      )}
      {screen === 'menu' && <Menu diff={diff} setDiff={setDiff} records={records} muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />}
      {screen === 'shop' && shop && (
        <Workshop d={shop} onBuy={(id: UpgId) => shopAct(g => g.buy(id))} onRepair={() => shopAct(g => g.repair())} onClose={openShop} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useRef } from 'react';
import type { PointerEvent as RPE, ReactNode } from 'react';
import clsx from 'clsx';
import { Anchor, Gauge, Pause, Radar, Rocket, Shield, Volume2, VolumeX, Wind, Wrench, Zap } from 'lucide-react';
import { ZONES } from '../game/config';
import type { HudData, MsgKind } from '../game/engine';
import type { Input } from '../game/input';

export interface Msg { id: number; text: string; kind: MsgKind }
interface Props {
  hud: HudData | null; msgs: Msg[]; muted: boolean; touch: boolean; input: Input | null;
  onMute: () => void; onPause: () => void; onShop: () => void; onSonar: () => void; onTorpedo: () => void;
  sonarRef: (c: HTMLCanvasElement | null) => void;
}

function Bar({ icon, label, value, max, color, warn }: { icon: ReactNode; label: string; value: number; max: number; color: string; warn?: boolean }) {
  const k = Math.max(0, Math.min(1, value / max));
  return (
    <div className={clsx('w-56 max-w-[46vw]', warn && 'ab-pulse')}>
      <div className="flex items-center justify-between text-[10px] tracking-[0.25em] text-cyan-100/70">
        <span className="flex items-center gap-1">{icon}{label}</span><span className="ab-mono text-white/90">{Math.ceil(value)}</span>
      </div>
      <div className="mt-1 h-2 rounded-full bg-black/50 ring-1 ring-white/10 overflow-hidden">
        <div className="h-full rounded-full transition-[width] duration-150" style={{ width: `${k * 100}%`, background: color, boxShadow: `0 0 12px ${color}` }} />
      </div>
    </div>
  );
}

function Joystick({ input }: { input: Input | null }) {
  const base = useRef<HTMLDivElement>(null); const knob = useRef<HTMLDivElement>(null);
  const move = (e: RPE<HTMLDivElement>) => {
    if (!input || !base.current || !knob.current) return;
    const r = base.current.getBoundingClientRect(); const R = r.width / 2;
    let x = (e.clientX - r.left - R) / R, y = (e.clientY - r.top - R) / R; const l = Math.hypot(x, y); if (l > 1) { x /= l; y /= l; }
    input.touch.x = x; input.touch.y = y; input.touch.active = true;
    knob.current.style.transform = `translate(${x * R * 0.6}px, ${y * R * 0.6}px)`;
  };
  const end = () => { if (input) { input.touch.active = false; input.touch.x = 0; input.touch.y = 0; } if (knob.current) knob.current.style.transform = ''; };
  return (
    <div ref={base} className="pointer-events-auto absolute left-5 bottom-6 h-32 w-32 rounded-full bg-cyan-400/10 ring-2 ring-cyan-200/30 grid place-items-center touch-none"
      onPointerDown={e => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); move(e); }} onPointerMove={e => e.buttons && move(e)} onPointerUp={end} onPointerCancel={end}>
      <div ref={knob} className="h-14 w-14 rounded-full bg-cyan-200/40 ring-2 ring-cyan-100/60 shadow-[0_0_20px_rgba(95,245,255,0.5)]" />
    </div>
  );
}

const MSG_STYLE: Record<MsgKind, string> = {
  big: 'text-xl sm:text-2xl font-bold text-cyan-100 drop-shadow-[0_0_14px_rgba(95,245,255,0.8)]',
  good: 'text-sm font-semibold text-amber-200 drop-shadow-[0_0_10px_rgba(255,200,80,0.7)]',
  warn: 'text-sm font-bold text-rose-300 drop-shadow-[0_0_10px_rgba(255,80,120,0.8)]',
  info: 'text-sm text-cyan-100/90',
};

export default function Hud({ hud, msgs, muted, touch, input, onMute, onPause, onShop, onSonar, onTorpedo, sonarRef }: Props) {
  const h = hud;
  const zone = ZONES[h?.zone ?? 0];
  const over = h ? h.depth > h.limit : false;
  const depthK = h ? Math.min(1, h.depth / h.limit) : 0;
  return (
    <div className="ab-font absolute inset-0 pointer-events-none text-white select-none">
      {h && (
        <div className="absolute left-3 top-3 sm:left-5 sm:top-4 ab-panel rounded-2xl px-4 py-3 space-y-2">
          <div className="flex items-end gap-3">
            <div className={clsx('ab-mono text-4xl sm:text-5xl font-bold leading-none', over ? 'text-rose-300 ab-pulse' : 'text-cyan-50')}>{Math.round(h.depth)}<span className="text-lg text-cyan-200/70"> m</span></div>
            <div className="pb-1 text-[10px] leading-tight tracking-[0.2em]">
              <div style={{ color: zone.color }} className="font-bold">{zone.name.toUpperCase()}</div>
              <div className="text-white/50">MÁX {Math.round(h.maxDepth)} m</div>
            </div>
          </div>
          <div className="w-56 max-w-[46vw]">
            <div className="flex justify-between text-[10px] tracking-[0.2em] text-white/55"><span className="flex items-center gap-1"><Gauge size={11} />PRESIÓN</span><span className="ab-mono">límite {h.limit} m</span></div>
            <div className="mt-1 h-2 rounded-full bg-black/50 ring-1 ring-white/10 overflow-hidden">
              <div className="h-full" style={{ width: `${depthK * 100}%`, background: over ? '#fb7185' : depthK > 0.85 ? '#fbbf24' : '#5eead4' }} />
            </div>
          </div>
          <Bar icon={<Wind size={11} />} label="OXÍGENO" value={h.o2} max={h.maxO2} color={h.o2 / h.maxO2 < 0.25 ? '#fb7185' : '#38bdf8'} warn={h.o2 / h.maxO2 < 0.25} />
          <Bar icon={<Anchor size={11} />} label="CASCO" value={h.hull} max={100} color={h.hull < 30 ? '#fb7185' : '#fbbf24'} warn={h.hull < 30} />
          {h.shield > 0 && <div className="flex items-center gap-1 text-xs text-violet-200 ab-pulse"><Shield size={13} /> Escudo eléctrico {Math.ceil(h.shield)} s</div>}
        </div>
      )}
      {h && (
        <div className="absolute right-3 top-3 sm:right-5 sm:top-4 flex flex-col items-end gap-2">
          <div className="flex gap-2 pointer-events-auto">
            <button aria-label="Silencio" onClick={onMute} className="h-9 w-9 grid place-items-center rounded-lg ab-panel">{muted ? <VolumeX size={16} /> : <Volume2 size={16} />}</button>
            <button aria-label="Pausa" onClick={onPause} className="h-9 w-9 grid place-items-center rounded-lg ab-panel"><Pause size={16} /></button>
          </div>
          <div className="ab-panel rounded-xl px-4 py-2 text-right">
            <div className="ab-mono text-2xl font-bold text-amber-200 drop-shadow-[0_0_10px_rgba(255,200,80,0.5)]">${h.money.toLocaleString('es-ES')}</div>
            <div className="text-[10px] tracking-[0.2em] text-white/60">BODEGA <span className="ab-mono text-amber-100">${h.cargo}</span></div>
            <div className="text-[10px] tracking-[0.2em] text-white/60">PUNTOS <span className="ab-mono text-cyan-100">{h.score.toLocaleString('es-ES')}</span></div>
          </div>
        </div>
      )}
      {h && (
        <div className={clsx('absolute flex flex-col items-center gap-2', touch ? 'right-3 top-44' : 'right-5 bottom-5')}>
          <canvas ref={sonarRef} className={clsx('rounded-full', touch ? 'h-24 w-24' : 'h-36 w-36')} />
          <div className="flex gap-3 text-[10px] tracking-[0.15em]">
            <span className={clsx('flex items-center gap-1', h.sonar >= 1 ? 'text-cyan-200' : 'text-white/40')}><Radar size={12} />{h.sonar >= 1 ? 'SONAR LISTO' : `${Math.round(h.sonar * 100)}%`}</span>
            <span className="flex items-center gap-1 text-orange-200"><Rocket size={12} /><span className="ab-mono">{h.torps}/{h.maxTorps}</span></span>
          </div>
        </div>
      )}
      {h?.atSurface && (
        <button onClick={onShop} className="pointer-events-auto absolute left-1/2 top-4 -translate-x-1/2 ab-btn rounded-xl px-5 py-2 font-bold text-slate-950 flex items-center gap-2 ab-float">
          <Wrench size={16} /> Taller (E)
        </button>
      )}
      <div className="absolute left-1/2 top-[22%] -translate-x-1/2 flex flex-col items-center gap-1 text-center w-[90%]">
        {msgs.map(m => <div key={m.id} className={clsx('ab-in', MSG_STYLE[m.kind])}>{m.text}</div>)}
      </div>
      {touch && h && (
        <>
          <Joystick input={input} />
          <div className="absolute right-4 bottom-6 flex flex-col gap-3 items-end pointer-events-auto">
            <div className="flex gap-3">
              <button onPointerDown={onTorpedo} className="h-16 w-16 rounded-full bg-orange-500/30 ring-2 ring-orange-200/50 grid place-items-center"><Rocket /></button>
              <button onPointerDown={onSonar} className="h-20 w-20 rounded-full bg-cyan-500/30 ring-2 ring-cyan-100/60 grid place-items-center"><Radar size={30} /></button>
            </div>
            <button onPointerDown={() => { if (input) input.touch.turbo = true; }} onPointerUp={() => { if (input) input.touch.turbo = false; }} onPointerLeave={() => { if (input) input.touch.turbo = false; }}
              className="h-12 w-28 rounded-full bg-teal-400/25 ring-2 ring-teal-100/50 flex items-center justify-center gap-1 text-sm font-bold"><Zap size={16} /> Turbo</button>
          </div>
        </>
      )}
    </div>
  );
}

import { Anchor, Gem, Home, Play, Radar, RotateCcw, Skull, Timer, Trophy, Volume2, VolumeX, Waves } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { DIFFS } from '../game/config';
import type { DiffId, Records } from '../game/config';
import type { Summary } from '../game/engine';

const KEYS: Array<[string, string]> = [
  ['← → ↑ ↓ / WASD', 'Navegar'], ['Espacio', 'Pulso de sonar'], ['X / J', 'Torpedo'],
  ['Shift', 'Turbo (gasta O₂)'], ['E', 'Taller en superficie'], ['P / Esc', 'Pausa'],
];
const TIPS = ['Apunta el foco a los rapes: la luz los ahuyenta.', 'El sonar revela tesoros y aturde a las criaturas cercanas.', 'El botín solo se cobra al volver a la superficie.'];

interface MenuProps { diff: DiffId; setDiff: (d: DiffId) => void; records: Record<DiffId, Records>; muted: boolean; onMute: () => void; onPlay: () => void }

export function Menu({ diff, setDiff, records, muted, onMute, onPlay }: MenuProps) {
  const rec = records[diff];
  return (
    <div className="ab-font absolute inset-0 overflow-y-auto bg-gradient-to-r from-[#010a14]/90 via-[#021624]/55 to-transparent text-white">
      <div className="min-h-full flex items-center p-4 sm:p-10">
        <div className="w-full max-w-[470px] ab-in">
          <div className="flex items-center gap-2 text-cyan-300/80 text-[11px] tracking-[0.5em]"><Waves size={14} /> EXPEDICIÓN SUBMARINA</div>
          <h1 className="ab-title ab-glow-text mt-2 text-7xl sm:text-8xl font-bold tracking-[0.12em] leading-none">ABISMO</h1>
          <p className="mt-4 text-sm text-cyan-50/75 leading-relaxed">
            Desciende con tu batiscafo hacia la oscuridad absoluta. Tu foco es la única luz entre medusas, rapes y anguilas
            bioluminiscentes. Rescata tesoros, vigila el oxígeno y la presión, y mejora el casco para llegar más hondo.
          </p>
          <div className="mt-5 text-[10px] tracking-[0.35em] text-cyan-100/55">DIFICULTAD</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {(Object.keys(DIFFS) as DiffId[]).map(id => (
              <button key={id} onClick={() => setDiff(id)}
                className={clsx('rounded-xl px-3 py-2 text-left ring-1 transition', diff === id ? 'bg-cyan-500/25 ring-cyan-200/80 shadow-[0_0_22px_rgba(34,211,238,0.35)]' : 'bg-white/5 ring-white/15 hover:bg-white/10')}>
                <div className="font-bold tracking-wide">{DIFFS[id].label}</div>
                <div className="text-[10px] leading-tight text-white/60">{DIFFS[id].sub}</div>
              </button>
            ))}
          </div>
          <div className="mt-3 grid grid-cols-2 gap-2">
            <div className="flex items-center gap-2 rounded-xl ab-panel px-3 py-2"><Trophy className="text-amber-300" size={18} /><div><div className="text-[10px] tracking-widest text-white/55">RÉCORD</div><div className="ab-mono font-bold text-amber-200">{rec.score.toLocaleString('es-ES')}</div></div></div>
            <div className="flex items-center gap-2 rounded-xl ab-panel px-3 py-2"><Anchor className="text-cyan-300" size={18} /><div><div className="text-[10px] tracking-widest text-white/55">MÁX. PROFUNDIDAD</div><div className="ab-mono font-bold text-cyan-100">{rec.depth} m</div></div></div>
          </div>
          <div className="mt-5 flex gap-2">
            <button onClick={onPlay} className="ab-btn flex-1 flex items-center justify-center gap-3 rounded-xl py-4 text-2xl font-bold tracking-[0.2em] text-slate-950">
              <Play fill="currentColor" size={22} /> Jugar
            </button>
            <button aria-label="Silencio" onClick={onMute} className="w-14 grid place-items-center rounded-xl ab-panel">{muted ? <VolumeX size={20} /> : <Volume2 size={20} />}</button>
          </div>
          <div className="mt-5 grid grid-cols-2 gap-x-4 gap-y-1 text-xs">
            {KEYS.map(([k, v]) => <div key={k} className="flex gap-2"><span className="ab-mono text-cyan-200 whitespace-nowrap">{k}</span><span className="text-white/55">{v}</span></div>)}
          </div>
          <ul className="mt-4 space-y-1 text-[11px] text-cyan-100/55">
            {TIPS.map(t => <li key={t} className="flex gap-2"><Radar size={12} className="mt-0.5 shrink-0 text-cyan-300/60" />{t}</li>)}
          </ul>
        </div>
      </div>
    </div>
  );
}

function Overlay({ children }: { children: ReactNode }) {
  return <div className="ab-font absolute inset-0 grid place-items-center bg-[#010812]/65 backdrop-blur-[2px] p-4 text-white">{children}</div>;
}

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Overlay>
      <div className="ab-panel ab-in rounded-2xl p-6 w-full max-w-xs text-center">
        <div className="ab-title ab-glow-text text-4xl font-bold tracking-[0.2em]">PAUSA</div>
        <div className="mt-5 space-y-2">
          <button onClick={onResume} className="ab-btn w-full rounded-xl py-3 font-bold text-slate-950 flex items-center justify-center gap-2"><Play size={18} fill="currentColor" /> Continuar</button>
          <button onClick={onRestart} className="w-full rounded-xl py-3 bg-white/10 ring-1 ring-white/20 hover:bg-white/15 flex items-center justify-center gap-2"><RotateCcw size={18} /> Reiniciar</button>
          <button onClick={onMenu} className="w-full rounded-xl py-3 bg-white/10 ring-1 ring-white/20 hover:bg-white/15 flex items-center justify-center gap-2"><Home size={18} /> Menú</button>
        </div>
      </div>
    </Overlay>
  );
}

function Stat({ icon, label, value }: { icon: ReactNode; label: string; value: string }) {
  return (
    <div className="rounded-xl bg-black/30 ring-1 ring-white/10 px-3 py-2 text-left">
      <div className="flex items-center gap-1 text-[10px] tracking-widest text-white/55">{icon}{label}</div>
      <div className="ab-mono text-lg font-bold">{value}</div>
    </div>
  );
}

export function GameOverScreen({ s, onRetry, onMenu }: { s: Summary; onRetry: () => void; onMenu: () => void }) {
  const mm = Math.floor(s.time / 60), ss = Math.floor(s.time % 60).toString().padStart(2, '0');
  return (
    <Overlay>
      <div className="ab-panel ab-in rounded-2xl p-6 w-full max-w-md text-center">
        <div className="text-[11px] tracking-[0.45em] text-rose-300/80 flex items-center justify-center gap-2"><Skull size={14} /> FIN DE LA INMERSIÓN</div>
        <div className="mt-2 text-sm text-white/70">{s.cause}</div>
        <div className="ab-mono mt-3 text-5xl font-bold text-amber-200 drop-shadow-[0_0_16px_rgba(255,200,80,0.5)]">{s.score.toLocaleString('es-ES')}</div>
        <div className="text-[10px] tracking-[0.3em] text-white/50">PUNTOS · {DIFFS[s.diff].label.toUpperCase()}</div>
        {s.newRecord && <div className="mt-2 inline-flex items-center gap-2 rounded-full bg-amber-400/20 ring-1 ring-amber-200/60 px-3 py-1 text-amber-100 text-sm font-bold ab-pulse"><Trophy size={14} /> ¡Nuevo récord!</div>}
        <div className="mt-4 grid grid-cols-2 gap-2">
          <Stat icon={<Anchor size={11} />} label="PROFUNDIDAD" value={`${s.depth} m`} />
          <Stat icon={<Gem size={11} />} label="TESOROS" value={`${s.treasures} · $${s.earned}`} />
          <Stat icon={<Skull size={11} />} label="CRIATURAS" value={`${s.kills}`} />
          <Stat icon={<Timer size={11} />} label="TIEMPO" value={`${mm}:${ss}`} />
        </div>
        <div className="mt-5 flex gap-2">
          <button onClick={onRetry} className="ab-btn flex-1 rounded-xl py-3 font-bold text-slate-950 flex items-center justify-center gap-2"><RotateCcw size={18} /> Reintentar</button>
          <button onClick={onMenu} className="flex-1 rounded-xl py-3 bg-white/10 ring-1 ring-white/20 hover:bg-white/15 flex items-center justify-center gap-2"><Home size={18} /> Menú</button>
        </div>
      </div>
    </Overlay>
  );
}

import { Anchor, Gauge, Lightbulb, Radar, Rocket, Wind, Wrench, X } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { UPGS } from '../game/config';
