interface Props { d: ShopData; onBuy: (id: UpgId) => void; onRepair: () => void; onClose: () => void }

export default function Workshop({ d, onBuy, onRepair, onClose }: Props) {
  return (
    <div className="ab-font absolute inset-0 grid place-items-center bg-[#010812]/60 p-3 text-white overflow-y-auto">
      <div className="ab-panel ab-in rounded-2xl p-5 w-full max-w-2xl">
        <div className="flex items-center gap-3">
          <Wrench className="text-cyan-300" />
          <div>
            <div className="ab-title text-2xl font-bold tracking-[0.15em]">TALLER DEL BARCO</div>
