          </div>
          <div className="ml-auto ab-mono text-2xl font-bold text-amber-200">${d.money.toLocaleString('es-ES')}</div>
          <button aria-label="Cerrar" onClick={onClose} className="h-9 w-9 grid place-items-center rounded-lg bg-white/10 hover:bg-white/20"><X size={18} /></button>
