/** Sonido procedural (Web Audio): ambiente submarino, motor, sonar, efectos y música etérea. */
export class Sfx {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private engine: GainNode | null = null; private engOsc: OscillatorNode | null = null;
  private amb: GainNode | null = null; private ambSrc: AudioBufferSourceNode | null = null;
  private noiseBuf: AudioBuffer | null = null;
  private muted = false; private musicT = 0; private step = 0;
  musicOn = false;
  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume(); return; }
    const AC = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (!AC) return;
    const ctx: AudioContext = new AC(); this.ctx = ctx;
    this.master = ctx.createGain(); this.master.gain.value = this.muted ? 0 : 0.55; this.master.connect(ctx.destination);
    const len = ctx.sampleRate * 2; this.noiseBuf = ctx.createBuffer(1, len, ctx.sampleRate);
    const d = this.noiseBuf.getChannelData(0); let b = 0;
    for (let i = 0; i < len; i++) { b = b * 0.97 + (Math.random() * 2 - 1) * 0.03; d[i] = b * 6; } // ruido marrón
    // Rumor del océano
    this.amb = ctx.createGain(); this.amb.gain.value = 0;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 260;
    this.ambSrc = ctx.createBufferSource(); this.ambSrc.buffer = this.noiseBuf; this.ambSrc.loop = true;
    this.ambSrc.connect(lp); lp.connect(this.amb); this.amb.connect(this.master); this.ambSrc.start();
    // Motor eléctrico
    this.engine = ctx.createGain(); this.engine.gain.value = 0;
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 300;
    this.engOsc = ctx.createOscillator(); this.engOsc.type = 'triangle'; this.engOsc.frequency.value = 40;
    this.engOsc.connect(f); f.connect(this.engine); this.engine.connect(this.master); this.engOsc.start();
  }
  setMuted(m: boolean) { this.muted = m; if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.55, this.ctx.currentTime, 0.05); }
  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0) {
    if (!this.ctx || !this.master) return;
    const t = this.ctx.currentTime + delay;
    const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
    o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq * slide), t + dur);
    g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.012); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }
  private noise(dur: number, vol: number, freq: number, type: BiquadFilterType = 'lowpass') {
    if (!this.ctx || !this.master || !this.noiseBuf) return;
    const t = this.ctx.currentTime;
    const s = this.ctx.createBufferSource(); s.buffer = this.noiseBuf;
    const f = this.ctx.createBiquadFilter(); f.type = type; f.frequency.setValueAtTime(freq, t); f.frequency.exponentialRampToValueAtTime(50, t + dur);
    const g = this.ctx.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    s.connect(f); f.connect(g); g.connect(this.master); s.start(t); s.stop(t + dur);
  }
  sonar() { this.tone(1180, 1.6, 'sine', 0.16, 0.98); this.tone(1180, 1.2, 'sine', 0.05, 0.98, 0.55); this.tone(1180, 0.9, 'sine', 0.02, 0.98, 1.05); }
  torpedo() { this.noise(0.5, 0.35, 1800, 'bandpass'); this.tone(300, 0.35, 'sawtooth', 0.05, 0.4); }
  boom() { this.noise(1.3, 0.9, 900); this.tone(55, 1.1, 'sine', 0.45, 0.4); }
  bubble() { this.tone(500 + Math.random() * 500, 0.08, 'sine', 0.05, 2.2); }
  shock() { this.noise(0.3, 0.4, 4000, 'highpass'); this.tone(90, 0.3, 'square', 0.08, 1.3); }
  bite() { this.noise(0.25, 0.6, 700); this.tone(140, 0.25, 'sawtooth', 0.12, 0.5); }
  creak() { this.tone(70 + Math.random() * 30, 1.1, 'sawtooth', 0.06, 0.7); this.noise(0.6, 0.1, 400); }
  treasure(big = false) { const n = big ? [523, 659, 784, 1046, 1318] : [784, 1046, 1318]; n.forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.09, 1, i * 0.07)); }
  pickup() { [440, 660, 880].forEach((f, i) => this.tone(f, 0.2, 'sine', 0.1, 1.2, i * 0.05)); }
  coin() { this.tone(1318, 0.12, 'square', 0.04); this.tone(1760, 0.25, 'square', 0.04, 1, 0.08); }
  alarm() { this.tone(880, 0.16, 'square', 0.05); this.tone(660, 0.16, 'square', 0.05, 1, 0.18); }
  deny() { this.tone(150, 0.2, 'square', 0.07, 0.8); }
  upgrade() { [392, 523, 659, 784].forEach((f, i) => this.tone(f, 0.3, 'triangle', 0.09, 1, i * 0.06)); }
  splash() { this.noise(0.8, 0.35, 2500); }
  setEngine(v: number, depth: number) {
    if (!this.ctx || !this.engine || !this.engOsc || !this.amb) return;
    const t = this.ctx.currentTime;
    this.engine.gain.setTargetAtTime(0.015 + v * 0.06, t, 0.15);
    this.engOsc.frequency.setTargetAtTime(38 + v * 34, t, 0.2);
    this.amb.gain.setTargetAtTime(0.18 + Math.min(0.25, depth / 1600), t, 0.5);
  }
  /** Música: acordes suaves y notas cristalinas cada vez más graves al bajar. */
  tick(dt: number, depth: number) {
    if (!this.ctx || !this.musicOn) return;
    this.musicT -= dt; if (this.musicT > 0) return;
    this.musicT = 0.5;
    const shift = depth > 200 ? 0.5 : depth > 60 ? 0.75 : 1;
    const chords = [[220, 261.6, 329.6], [196, 246.9, 293.7], [174.6, 220, 261.6], [164.8, 207.7, 246.9]];
    const c = chords[Math.floor(this.step / 16) % 4];
    if (this.step % 16 === 0) c.forEach(f => this.tone(f * shift * 0.5, 7, 'sine', 0.03));
    if (this.step % 2 === 0 && Math.random() < 0.7) this.tone(c[(this.step / 2) % 3 | 0] * 2 * shift, 1.4, 'sine', 0.025);
    this.step++;
  }
  stopEngine() { if (this.engine && this.ctx) this.engine.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1); }
  dispose() { try { this.engOsc?.stop(); this.ambSrc?.stop(); this.ctx?.close(); } catch { /* ya cerrado */ } this.ctx = null; }
}

import { fbm1, noise1 } from './noise';

