export interface Zone { depth: number; name: string; color: string }
export const ZONES: Zone[] = [
  { depth: 0, name: 'Zona fótica', color: '#7dd3fc' },
  { depth: 60, name: 'Zona crepuscular', color: '#38bdf8' },
  { depth: 200, name: 'Zona abisal', color: '#a78bfa' },
