/** Color del agua por profundidad (fondo y niebla). */
const WATER: Array<[number, number, number, number]> = [
  [0, 0.13, 0.45, 0.6], [15, 0.05, 0.24, 0.36], [40, 0.02, 0.1, 0.19], [100, 0.01, 0.045, 0.1], [250, 0.005, 0.02, 0.05], [600, 0.003, 0.008, 0.025],
];
export function waterColor(depth: number, out: { r: number; g: number; b: number }) {
  let i = 0; while (i < WATER.length - 2 && depth > WATER[i + 1][0]) i++;
  const a = WATER[i], b = WATER[i + 1]; const t = Math.max(0, Math.min(1, (depth - a[0]) / (b[0] - a[0])));
  out.r = a[1] + (b[1] - a[1]) * t; out.g = a[2] + (b[2] - a[2]) * t; out.b = a[3] + (b[3] - a[3]) * t;
  return out;
}
/** 1 en la superficie, 0 en la oscuridad total. */
export const sunlight = (depth: number) => Math.exp(-Math.max(0, depth) / 26);

/** Perfil del lecho marino (y del fondo en el plano de juego): playa a la izquierda, talud que cae a la derecha. */
export function floorY(x: number) {
  if (x < 0) return Math.min(-2, -30 - x * 0.55 + noise1(x * 0.11) * 3);
  const slope = -30 - x * 0.62;
  const k = Math.min(1, x / 90);
  const terr = (fbm1(x * 0.012 + 7) - 0.5) * 70 * k + (noise1(x * 0.09) - 0.5) * 7;
  const steps = Math.floor(x / 140) * -14;
  return Math.min(-6, slope + terr + steps);
}
export const SURFACE_Y = -0.8;

export interface Records { score: number; depth: number }
const REC_KEY = 'abismo-records';
export function loadRecords(): Record<DiffId, Records> {
  const base = { facil: { score: 0, depth: 0 }, normal: { score: 0, depth: 0 }, dificil: { score: 0, depth: 0 } };
  try { return { ...base, ...JSON.parse(localStorage.getItem(REC_KEY) || '{}') }; } catch { return base; }
}
export function saveRecord(d: DiffId, score: number, depth: number) {
  const all = loadRecords(); const r = all[d];
  const newRecord = score > r.score;
  all[d] = { score: Math.max(r.score, score), depth: Math.max(r.depth, depth) };
  try { localStorage.setItem(REC_KEY, JSON.stringify(all)); } catch { /* sin almacenamiento */ }
  return newRecord;
}

import * as THREE from 'three';
import { floorY, SURFACE_Y } from './config';
import { glowSprite } from './effects';

export type Kind = 'medusa' | 'rape' | 'anguila';
export const CREATURES: Record<Kind, { name: string; hp: number; dmg: number; points: number; color: number }> = {
  medusa: { name: 'Medusa', hp: 1, dmg: 7, points: 15, color: 0xff5ad8 },
  rape: { name: 'Rape abisal', hp: 3, dmg: 15, points: 60, color: 0x6ff7ff },
  anguila: { name: 'Anguila eléctrica', hp: 2, dmg: 11, points: 45, color: 0x5dff9d },
};
export interface Creature {
  kind: Kind; g: THREE.Group; pos: THREE.Vector3; vel: THREE.Vector3; hp: number; stun: number; phase: number;
  cd: number; flee: number; dash: number; home: THREE.Vector3; parts: THREE.Object3D[]; trail: THREE.Vector3[]; glow: THREE.Sprite[];
}
export interface Ctx { sub: THREE.Vector3; lamp: THREE.Vector3; dir: THREE.Vector3; range: number; tan: number; density: number; alive: boolean }

const JELLY_COLORS = [0xff1aa8, 0x00c8ff, 0x7b2bff, 0xff5a00];
const _v = new THREE.Vector3();

export class Creatures {
  list: Creature[] = [];
  private geo = {
    bell: new THREE.SphereGeometry(1, 20, 10, 0, Math.PI * 2, 0, Math.PI / 2), core: new THREE.SphereGeometry(0.45, 12, 8),
    body: new THREE.SphereGeometry(1, 16, 12), tooth: new THREE.ConeGeometry(0.07, 0.32, 4), tail: new THREE.ConeGeometry(0.6, 1.2, 6),
    seg: new THREE.SphereGeometry(0.42, 10, 8), lure: new THREE.SphereGeometry(0.16, 10, 8),
    stalk: new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0.6, 0.85, 0), new THREE.Vector3(1.3, 1.6, 0), new THREE.Vector3(2.0, 1.25, 0)]),
    tent: new THREE.BufferGeometry(),
  };
  private mat = {
    dark: new THREE.MeshStandardMaterial({ color: 0x1a1018, roughness: 0.4, metalness: 0.5, emissive: 0x12030a }),
    eel: new THREE.MeshStandardMaterial({ color: 0x1f3a3c, roughness: 0.5, metalness: 0.3, emissive: 0x03140d }),
    tooth: new THREE.MeshBasicMaterial({ color: 0xe8f0ff }),
    lure: new THREE.MeshBasicMaterial({ color: 0xbffcff }),
    line: new THREE.LineBasicMaterial({ color: 0x6ff7ff, transparent: true, opacity: 0.6 }),
    jelly: JELLY_COLORS.map(c => new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: 0.32, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })),
    tentL: JELLY_COLORS.map(c => new THREE.LineBasicMaterial({ color: c, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending })),
  };
  private fish: THREE.InstancedMesh; private fishMat = new THREE.MeshStandardMaterial({ color: 0xa8c4d4, roughness: 0.3, metalness: 0.6, emissive: 0x000000 });
  private fishGeo = new THREE.ConeGeometry(0.16, 0.7, 5).rotateZ(-Math.PI / 2);
  private schools = [0, 1, 2, 3].map(() => ({ c: new THREE.Vector3(), r: 4, ph: Math.random() * 9 }));
  private spawnT = 0;
  constructor(private scene: THREE.Scene) {
    const pts: THREE.Vector3[] = [];
    for (let s = 0; s < 7; s++) { const a = (s / 7) * Math.PI * 2; for (let k = 0; k < 6; k++) { pts.push(new THREE.Vector3(Math.cos(a) * 0.75, -k * 0.45, Math.sin(a) * 0.75), new THREE.Vector3(Math.cos(a) * 0.75 + Math.sin(k) * 0.1, -(k + 1) * 0.45, Math.sin(a) * 0.75)); } }
    this.geo.tent.setFromPoints(pts);
    this.fish = new THREE.InstancedMesh(this.fishGeo, this.fishMat, 96); this.fish.frustumCulled = false; scene.add(this.fish);
  }
  private make(kind: Kind, x: number, y: number, z = 0): Creature {
    const g = new THREE.Group(); const parts: THREE.Object3D[] = []; const glow: THREE.Sprite[] = [];
    if (kind === 'medusa') {
      const ci = Math.floor(Math.random() * JELLY_COLORS.length); const col = JELLY_COLORS[ci];
      const bell = new THREE.Mesh(this.geo.bell, this.mat.jelly[ci]); bell.scale.set(1.1, 0.9, 1.1);
      const core = new THREE.Mesh(this.geo.core, this.mat.jelly[ci]); core.position.y = 0.2; core.scale.setScalar(0.7);
      const tent = new THREE.LineSegments(this.geo.tent, this.mat.tentL[ci]);
      const gl = glowSprite(col, 7, 0.45); gl.position.y = 0.1; glow.push(gl);
      g.add(bell, core, tent, gl); parts.push(bell, tent);
      const s = 0.7 + Math.random() * 0.9; g.scale.setScalar(s);
    } else if (kind === 'rape') {
      const body = new THREE.Mesh(this.geo.body, this.mat.dark); body.scale.set(1.35, 1.05, 0.95);
      const jaw = new THREE.Mesh(this.geo.bell, this.mat.dark); jaw.rotation.z = Math.PI; jaw.scale.set(1.25, 0.55, 0.9); jaw.position.set(0.25, -0.25, 0);
      const fin = new THREE.Mesh(this.geo.tail, this.mat.dark); fin.scale.set(0.5, 0.9, 0.12); fin.position.set(-0.3, 1.0, 0); fin.rotation.z = 0.7;
      g.add(jaw, fin);
      const tail = new THREE.Mesh(this.geo.tail, this.mat.dark); tail.rotation.z = Math.PI / 2; tail.position.x = -1.6; tail.scale.set(1, 1, 0.4);
      for (let i = 0; i < 9; i++) {
        const top = i % 2 === 0; const t = new THREE.Mesh(this.geo.tooth, this.mat.tooth);
        const a = -0.55 + (i / 8) * 1.1; t.position.set(1.2 - Math.abs(a) * 0.4, top ? 0.0 : -0.35, a * 0.75); t.rotation.z = top ? Math.PI : 0; t.scale.setScalar(1.4); g.add(t);
      }
      const stalk = new THREE.Line(this.geo.stalk, this.mat.line);
      const lure = new THREE.Mesh(this.geo.lure, this.mat.lure); lure.position.set(2.0, 1.25, 0);
      const gl = glowSprite(0x6ff7ff, 5.5, 0.95); gl.position.copy(lure.position); glow.push(gl);
      const eye = glowSprite(0xfff27a, 0.7, 0.9); eye.position.set(0.9, 0.45, 0.55); glow.push(eye);
      g.add(body, tail, stalk, lure, gl, eye); parts.push(tail, lure);
      g.scale.setScalar(0.9 + Math.random() * 0.5);
    } else {
      for (let i = 0; i < 12; i++) {
        const m = new THREE.Mesh(this.geo.seg, this.mat.eel); const s = i === 0 ? 1.1 : 1 - i * 0.065; m.scale.set(s * 1.3, s, s);
        g.add(m); parts.push(m);
        if (i % 3 === 1) { const gl = glowSprite(0x5dff9d, 1.6, 0.85); m.add(gl); glow.push(gl); }
      }
      const eye = glowSprite(0xff4466, 0.6, 1); eye.position.set(0.35, 0.18, 0.25); parts[0].add(eye); glow.push(eye);
    }
    this.scene.add(g); g.position.set(x, y, z);
