/** Entrada unificada: teclado en window + joystick y botones táctiles. */
export interface InputState { x: number; y: number; turbo: boolean }

export class Input {
  state: InputState = { x: 0, y: 0, turbo: false };
  touch = { x: 0, y: 0, active: false, turbo: false };
  onPause: (() => void) | null = null;
  onSonar: (() => void) | null = null;
  onTorpedo: (() => void) | null = null;
  onShop: (() => void) | null = null;
  onAnyKey: (() => void) | null = null;
  private keys = new Set<string>();
  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    this.onAnyKey?.();
    if (!e.repeat) {
      if (k === 'Escape' || k === 'KeyP') { this.onPause?.(); return; }
      if (k === 'Space') this.onSonar?.();
      if (k === 'KeyX' || k === 'KeyJ') this.onTorpedo?.();
      if (k === 'KeyE' || k === 'Enter') this.onShop?.();
    }
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); };
  private blur = () => { this.keys.clear(); };
  attach() {
    window.addEventListener('keydown', this.down); window.addEventListener('keyup', this.up); window.addEventListener('blur', this.blur);
  }
  detach() {
    window.removeEventListener('keydown', this.down); window.removeEventListener('keyup', this.up); window.removeEventListener('blur', this.blur);
  }
  update() {
    const k = this.keys; let x = 0, y = 0;
    if (k.has('ArrowLeft') || k.has('KeyA')) x -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) x += 1;
    if (k.has('ArrowUp') || k.has('KeyW')) y += 1;
    if (k.has('ArrowDown') || k.has('KeyS')) y -= 1;
    if (this.touch.active) { x += this.touch.x; y -= this.touch.y; }
    this.state.x = Math.max(-1, Math.min(1, x));
    this.state.y = Math.max(-1, Math.min(1, y));
    this.state.turbo = k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.turbo;
  }
  reset() {
    this.keys.clear(); this.state = { x: 0, y: 0, turbo: false };
    Object.assign(this.touch, { x: 0, y: 0, active: false, turbo: false });
  }
}

