    box: new THREE.BoxGeometry(1, 1, 1), coin: new THREE.CylinderGeometry(0.28, 0.28, 0.07, 14), half: new THREE.SphereGeometry(0.55, 14, 8, 0, Math.PI * 2, 0, Math.PI / 2),
