        const lid = this.mesh(G.box, this.wood, g, -0.1, 0.78, 0); lid.scale.set(1.3, 0.25, 0.8); lid.rotation.z = 0.35;
        this.mesh(G.box, this.gold, g, 0, 0.3, 0).scale.set(1.34, 0.12, 0.84);
