      case 'kit': this.mesh(G.box, this.white, g).scale.set(0.9, 0.7, 0.5); this.mesh(G.box, this.red, g, 0, 0, 0.26).scale.set(0.5, 0.14, 0.02); this.mesh(G.box, this.red, g, 0, 0, 0.26).scale.set(0.14, 0.5, 0.02); break;
