/** Ruido de valor 1D/2D determinista y fbm, sin dependencias. */
function hash(n: number) { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); }
function hash2(x: number, y: number) { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); }
const fade = (t: number) => t * t * (3 - 2 * t);

export function noise1(x: number) {
  const i = Math.floor(x), f = x - i;
  return hash(i) * (1 - fade(f)) + hash(i + 1) * fade(f);
}

export function noise2(x: number, y: number) {
  const ix = Math.floor(x), iy = Math.floor(y), fx = fade(x - ix), fy = fade(y - iy);
  const a = hash2(ix, iy), b = hash2(ix + 1, iy), c = hash2(ix, iy + 1), d = hash2(ix + 1, iy + 1);
  return (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
}

export function fbm1(x: number, oct = 4) {
  let s = 0, a = 0.5, f = 1, n = 0;
  for (let i = 0; i < oct; i++) { s += noise1(x * f) * a; n += a; a *= 0.5; f *= 2.03; }
  return s / n;
}

export function fbm2(x: number, y: number, oct = 4) {
  let s = 0, a = 0.5, f = 1, n = 0;
  for (let i = 0; i < oct; i++) { s += noise2(x * f, y * f) * a; n += a; a *= 0.5; f *= 2.03; }
  return s / n;
}

/** Generador pseudoaleatorio con semilla (mulberry32). */
export function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0; let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

import { floorY } from './config';

export interface Blip { x: number; y: number; kind: 'enemy' | 'treasure' | 'pickup' }

/** Pantalla de sonar circular: perfil del fondo, barrido y ecos detectados. */
export function drawSonar(c: HTMLCanvasElement, subX: number, subY: number, radius: number, sweep: number, blips: Blip[], echo: number) {
  const dpr = Math.min(window.devicePixelRatio || 1, 2); const S = c.clientWidth || 140;
  if (c.width !== Math.round(S * dpr)) { c.width = Math.round(S * dpr); c.height = Math.round(S * dpr); }
  const g = c.getContext('2d'); if (!g) return;
  g.setTransform(dpr, 0, 0, dpr, 0, 0);
  const R = S / 2; const k = (R - 4) / radius;
  g.clearRect(0, 0, S, S);
  g.save(); g.beginPath(); g.arc(R, R, R - 2, 0, Math.PI * 2); g.clip();
  const bg = g.createRadialGradient(R, R, 0, R, R, R); bg.addColorStop(0, 'rgba(6,40,46,0.92)'); bg.addColorStop(1, 'rgba(2,14,20,0.95)');
  g.fillStyle = bg; g.fillRect(0, 0, S, S);
  g.strokeStyle = 'rgba(95,245,255,0.14)'; g.lineWidth = 1;
  for (let i = 1; i <= 3; i++) { g.beginPath(); g.arc(R, R, (R - 4) * i / 3, 0, Math.PI * 2); g.stroke(); }
  g.beginPath(); g.moveTo(R, 0); g.lineTo(R, S); g.moveTo(0, R); g.lineTo(S, R); g.stroke();
  // Superficie
  const sy = R - (0 - subY) * k; if (sy > 0) { g.fillStyle = 'rgba(125,211,252,0.25)'; g.fillRect(0, 0, S, sy); }
  // Perfil del lecho marino
  g.beginPath(); g.moveTo(0, S);
  for (let px = 0; px <= S; px += 3) { const wx = subX + (px - R) / k; g.lineTo(px, R - (floorY(wx) - subY) * k); }
  g.lineTo(S, S); g.closePath();
  g.fillStyle = 'rgba(40,120,110,0.45)'; g.fill(); g.strokeStyle = 'rgba(110,255,200,0.7)'; g.stroke();
  // Barrido
  const a = sweep * Math.PI * 2; const grd = (g as any).createConicGradient ? (g as any).createConicGradient(a - 0.8, R, R) : null;
  if (grd) {
    grd.addColorStop(0, 'rgba(95,245,255,0)'); grd.addColorStop(0.127, 'rgba(95,245,255,0.28)'); grd.addColorStop(0.13, 'rgba(95,245,255,0)');
    g.fillStyle = grd; g.fillRect(0, 0, S, S);
  }
  g.strokeStyle = 'rgba(160,255,255,0.8)'; g.beginPath(); g.moveTo(R, R); g.lineTo(R + Math.cos(a) * R, R + Math.sin(a) * R); g.stroke();
  // Pulso activo
  if (echo > 0) { g.strokeStyle = `rgba(160,255,255,${echo})`; g.lineWidth = 2; g.beginPath(); g.arc(R, R, (1 - echo) * (R - 4), 0, Math.PI * 2); g.stroke(); }
  for (const b of blips) {
    const px = R + (b.x - subX) * k, py = R - (b.y - subY) * k;
    if (Math.hypot(px - R, py - R) > R - 3) continue;
    g.fillStyle = b.kind === 'enemy' ? '#ff5577' : b.kind === 'treasure' ? '#ffd34d' : '#7dd3fc';
    g.shadowColor = g.fillStyle; g.shadowBlur = 6;
    g.beginPath(); g.arc(px, py, b.kind === 'enemy' ? 2.6 : 3, 0, Math.PI * 2); g.fill();
  }
  g.shadowBlur = 0;
  g.fillStyle = '#ffffff'; g.beginPath(); g.moveTo(R + 5, R); g.lineTo(R - 4, R - 3.5); g.lineTo(R - 4, R + 3.5); g.closePath(); g.fill();
  g.restore();
  g.strokeStyle = 'rgba(95,245,255,0.55)'; g.lineWidth = 2; g.beginPath(); g.arc(R, R, R - 2, 0, Math.PI * 2); g.stroke();
}

