.ab-font { font-family: 'Avenir Next', 'Segoe UI', system-ui, -apple-system, sans-serif; }
.ab-title { font-family: Futura, 'Century Gothic', 'Avenir Next', 'Trebuchet MS', system-ui, sans-serif; }
.ab-mono { font-family: 'JetBrains Mono', 'SFMono-Regular', ui-monospace, Menlo, Consolas, monospace; font-variant-numeric: tabular-nums; }
.ab-glow-text {
  background: linear-gradient(180deg, #e6fdff 0%, #7ff3ff 40%, #2aa6c9 75%, #0b4f73 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 22px rgba(95, 245, 255, 0.45));
}
.ab-panel {
  background: linear-gradient(165deg, rgba(4, 30, 44, 0.78), rgba(2, 10, 20, 0.88));
  border: 1px solid rgba(95, 245, 255, 0.2);
  box-shadow: 0 0 40px rgba(20, 160, 200, 0.16), inset 0 0 28px rgba(95, 245, 255, 0.05);
  backdrop-filter: blur(6px);
}
.ab-btn {
  background: linear-gradient(90deg, #0ea5b7, #22d3ee 50%, #5eead4);
  box-shadow: 0 0 28px rgba(34, 211, 238, 0.5); transition: transform 0.15s ease, box-shadow 0.15s ease, filter 0.15s;
}
.ab-btn:hover { transform: translateY(-1px); filter: brightness(1.1); box-shadow: 0 0 40px rgba(94, 234, 212, 0.65); }
@keyframes ab-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
.ab-in { animation: ab-in 0.4s ease-out both; }
@keyframes ab-pulse { 0%, 100% { opacity: 0.55; } 50% { opacity: 1; } }
.ab-pulse { animation: ab-pulse 1s ease-in-out infinite; }
@keyframes ab-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-4px); } }
.ab-float { animation: ab-float 3.2s ease-in-out infinite; }
